def _amount(tok):
    if tok and all("0" <= c <= "9" for c in tok):
        return int(tok)
    return None


def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple] = []
    rejected: list[int] = []

    for idx, op in enumerate(ops):
        t = op.split(" ")
        verb = t[0]
        n = len(t)
        ok = False
        record = None

        if verb == "open" and n == 3:
            name, amt = t[1], _amount(t[2])
            if amt is not None and name not in balances:
                record = ("open", name)
                balances[name] = amt
                ok = True

        elif verb == "deposit" and n == 3:
            name, amt = t[1], _amount(t[2])
            if amt is not None and amt > 0 and name in balances:
                record = ("bal", name, balances[name])
                balances[name] += amt
                ok = True

        elif verb == "withdraw" and n == 3:
            name, amt = t[1], _amount(t[2])
            if (amt is not None and amt > 0 and name in balances
                    and name not in frozen and balances[name] >= amt):
                record = ("bal", name, balances[name])
                balances[name] -= amt
                ok = True

        elif verb == "transfer" and n == 4:
            a, b, amt = t[1], t[2], _amount(t[3])
            if (amt is not None and amt > 0 and a != b
                    and a in balances and b in balances
                    and a not in frozen and balances[a] >= amt):
                record = ("pair", a, balances[a], b, balances[b])
                balances[a] -= amt
                balances[b] += amt
                ok = True

        elif verb == "freeze" and n == 2:
            name = t[1]
            if name in balances and name not in frozen:
                record = ("frz", name, False)
                frozen.add(name)
                ok = True

        elif verb == "unfreeze" and n == 2:
            name = t[1]
            if name in balances and name in frozen:
                record = ("frz", name, True)
                frozen.discard(name)
                ok = True

        elif verb == "undo" and n == 1:
            if history:
                rec = history.pop()
                kind = rec[0]
                if kind == "open":
                    del balances[rec[1]]
                    frozen.discard(rec[1])
                elif kind == "bal":
                    balances[rec[1]] = rec[2]
                elif kind == "pair":
                    balances[rec[1]] = rec[2]
                    balances[rec[3]] = rec[4]
                elif kind == "frz":
                    if rec[2]:
                        frozen.add(rec[1])
                    else:
                        frozen.discard(rec[1])
                ok = True

        if ok:
            if record is not None:
                history.append(record)
        else:
            rejected.append(idx)

    return balances, rejected
